$$('.mq').forEach(m=>{m.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')m.classList.add('hold')});m.addEventListener('pointerleave',()=>m.classList.remove('hold'))});
(function startMq(){const t=$$('.mqt');const go=()=>requestAnimationFrame(()=>requestAnimationFrame(()=>t.forEach(x=>{x.classList.remove('run');void x.offsetWidth;x.classList.add('run')})));
  const imgs=$$('.mqt img');let n=imgs.filter(i=>!i.complete).length;if(!n)go();else imgs.forEach(i=>{if(!i.complete)i.addEventListener('load',()=>{if(--n===0)go()},{once:true})});go();
  addEventListener('pageshow',go);document.addEventListener('visibilitychange',()=>{if(!document.hidden)go()})})();
const ax=$('#ax'),axI=$('#axI'),axP=$('#axp');let axSrc=null,axBusy=false,axT=[];
const ease='cubic-bezier(.2,.9,.2,1)';let lockY=0;function lockPage(on){const b=document.body.style;if(on){lockY=scrollY;Object.assign(b,{position:'fixed',top:-lockY+'px',left:'0',right:'0',overflow:'hidden'})}else{Object.assign(b,{position:'',top:'',left:'',right:'',overflow:''});scrollTo(0,lockY)}}
function rectOf(el){const r=(el.querySelector('img')||el).getBoundingClientRect();return {x:r.left,y:r.top,w:r.width,h:r.height}}
function axPlace(r){axI.style.width=r.w+'px';axI.style.height=r.h+'px';axI.style.transform=`translate(${r.x}px,${r.y}px)`}
function fly(from,to,dur){return axI.animate([{width:from.w+'px',height:from.h+'px',transform:`translate(${from.x}px,${from.y}px)`},{width:to.w+'px',height:to.h+'px',transform:`translate(${to.x}px,${to.y}px)`}],{duration:reduce?1:dur,easing:ease,fill:'forwards'}).finished}
function sparks(cx,cy){if(reduce)return;for(let i=0;i<14;i++){const d=document.createElement('i');d.className='spk';d.style.left=cx+'px';d.style.top=cy+'px';ax.appendChild(d);const a=i/14*6.283+Math.random()*.3,r=90+Math.random()*70;
  d.animate([{transform:'translate(-50%,-50%) scale(1)',opacity:1},{transform:`translate(calc(-50% + ${Math.cos(a)*r}px),calc(-50% + ${Math.sin(a)*r}px)) scale(.2)`,opacity:0}],{duration:800+Math.random()*300,easing:'cubic-bezier(.1,.8,.3,1)'}).finished.then(()=>d.remove())}}
