(function(){const c=$('#stars'),x=c.getContext('2d');let W,H,D,L=[],shoot=null,t0=performance.now(),sy=scrollY;
  function mk(){D=Math.min(devicePixelRatio||1,2);W=c.width=innerWidth*D;H=c.height=innerHeight*D;L=[[150,.35,.9,.04],[90,.7,1.4,.1],[30,1.2,2.2,.2]].map(([n,r0,r1,par])=>({par,s:Array.from({length:n},()=>({x:Math.random()*W,y:Math.random()*H,r:(r0+Math.random()*(r1-r0))*D,tw:Math.random()*6.28,sp:.6+Math.random()*1.8,hue:Math.random()<.18?1:0}))}))}
  mk();addEventListener('resize',mk);
  function draw(now){const t=(now-t0)/1000,off=scrollY;x.clearRect(0,0,W,H);
    L.forEach(l=>{const dy=(off*l.par*D)%H;l.s.forEach(s=>{let y=s.y-dy;if(y<0)y+=H;const a=.35+.65*(.5+.5*Math.sin(t*s.sp+s.tw));
      x.beginPath();x.arc(s.x,y,s.r,0,6.283);x.fillStyle=s.hue?`rgba(255,120,135,${a})`:`rgba(255,248,250,${a})`;x.fill();
      if(s.r>1.8*D){x.globalAlpha=a*.35;x.fillRect(s.x-s.r*3,y-.4*D,s.r*6,.8*D);x.fillRect(s.x-.4*D,y-s.r*3,.8*D,s.r*6);x.globalAlpha=1}})});
    if(!shoot&&Math.random()<.006)shoot={x:Math.random()*W*.8+W*.2,y:Math.random()*H*.4,l:0,v:(9+Math.random()*6)*D};
    if(shoot){shoot.l+=1;const k=shoot.l,hx=shoot.x-k*shoot.v,hy=shoot.y+k*shoot.v*.45,g=x.createLinearGradient(hx,hy,hx+90*D,hy-40*D);
      g.addColorStop(0,'rgba(255,255,255,.95)');g.addColorStop(1,'rgba(255,60,80,0)');x.strokeStyle=g;x.lineWidth=2*D;x.beginPath();x.moveTo(hx,hy);x.lineTo(hx+90*D,hy-40*D);x.stroke();
      if(k>40)shoot=null}
  }
  if(reduce){draw(performance.now());return}
  (function f(now){if(!document.hidden)draw(now);requestAnimationFrame(f)})(performance.now());
})();
